<?php
$zipData = base64_decode('');
file_put_contents('deploy_double_click_fix.zip', $zipData);
$zip = new ZipArchive;
if ($zip->open('deploy_double_click_fix.zip') === TRUE) {
    $zip->extractTo('../');
    $zip->close();
    unlink('deploy_double_click_fix.zip');
    if (file_exists(__DIR__ . '/../bootstrap/cache/routes-v7.php')) unlink(__DIR__ . '/../bootstrap/cache/routes-v7.php');
    echo '<h1>Fix Deployed!</h1>';
} else {
    echo '<h1>Error extracting zip</h1>';
}
?>